class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        # Create a set of prime numbers up to 100 using Sieve of Eratosthenes
        is_prime = [True] * 101
        is_prime[0] = False
        is_prime[1] = False

        for i in range(2, 101):
            if is_prime[i]:
                for j in range(i * i, 101, i):
                    is_prime[j] = False

        # Find the first and last indices of prime numbers
        first_prime_index = -1
        last_prime_index = -1

        for i, num in enumerate(nums):
            if is_prime[num]:
                if first_prime_index == -1:
                    first_prime_index = i
                last_prime_index = i

        # Return the maximum distance between indices
        return last_prime_index - first_prime_index

