class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        def get_first_digit(num):
            # Extract first digit by repeatedly dividing by 10
            while num >= 10:
                num //= 10
            return num

        def gcd(a, b):
            # Euclidean algorithm to find GCD
            while b:
                a, b = b, a % b
            return a

        count = 0
        n = len(nums)

        # Check all pairs (i, j) where i < j
        for i in range(n):
            for j in range(i + 1, n):
                first_digit_i = get_first_digit(nums[i])
                last_digit_j = nums[j] % 10

                # Check if they are coprime
                if gcd(first_digit_i, last_digit_j) == 1:
                    count += 1

        return count

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        result = []

        for char in s:
            current_char = ord(char) - ord('a')

            # Try to change to 'a' (0)
            dist_to_a = current_char

            if dist_to_a <= k:
                result.append('a')
                k -= dist_to_a
            else:
                # We can't go to 'a', so find the smallest character we can reach
                for target in range(0, 26):
                    dist = min(abs(current_char - target), 26 - abs(current_char - target))
                    if dist <= k:
                        result.append(chr(ord('a') + target))
                        k -= dist
                        break

        return ''.join(result)

