class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        result = []
        remaining_k = k

        for char in s:
            # Try to find the smallest character we can change to
            # starting from 'a' and going up
            current_ord = ord(char)

            for target_ord in range(ord('a'), ord('z') + 1):
                target_char = chr(target_ord)
                # Calculate cyclic distance
                diff = abs(current_ord - target_ord)
                cyclic_dist = min(diff, 26 - diff)

                if cyclic_dist <= remaining_k:
                    result.append(target_char)
                    remaining_k -= cyclic_dist
                    break
            else:
                # If no character found (shouldn't happen), keep original
                result.append(char)

        return ''.join(result)

